import React, { Component } from 'react';
import axios from 'axios';
import MyContext from '../contexts/MyContext';
import '../css/ProductComponent.css';

class Product extends Component {
  static contextType = MyContext;

  constructor(props) {
    super(props);
    this.state = {
      products: [],
      categories: [],
      txtID: '',
      txtName: '',
      txtCostPrice: '',
      txtPrice: '',
      cmbCategory: '',
      cmbStatus: 'Active',
      imgProduct: '',
      imageFile: null,
      isSaving: false,
      isUploadingImage: false,
      isEdit: false,
      showConfirm: false,
      confirmMsg: '',
      onConfirmCallback: null,
      showToast: false,
      toastMsg: '',
      toastType: 'success'
    };
  }

  componentDidMount() {
    this.apiGetCategories();
    this.apiGetProducts();
    this.productRefreshTimer = setInterval(this.apiGetProducts, 5000);
  }

  componentWillUnmount() {
    clearInterval(this.productRefreshTimer);
    clearTimeout(this.toastTimer);
  }

  triggerToast = (msg, type = 'success') => {
    clearTimeout(this.toastTimer);
    this.setState({ showToast: true, toastMsg: msg, toastType: type });
    this.toastTimer = setTimeout(() => {
      this.setState({ showToast: false });
    }, 3500);
  };

  apiGetCategories = () => {
    const config = { headers: { 'x-access-token': this.context.token } };
    axios.get('/api/admin/categories', config).then((res) => {
      this.setState({
        categories: res.data,
        cmbCategory: res.data.length > 0 ? res.data[0]._id : ''
      });
    });
  };

  apiGetProducts = () => {
    const config = { headers: { 'x-access-token': this.context.token } };
    axios.get('/api/admin/products', config).then((res) => {
      this.setState({ products: res.data });
    });
  };

  // Hàm xử lý file chung cho cả bấm chọn và kéo thả
  processFile = (file) => {
    if (!file) return;
    if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) {
      this.triggerToast('Chỉ hỗ trợ ảnh JPG, PNG hoặc WebP.', 'error');
      return;
    }
    if (file.size > 8 * 1024 * 1024) {
      this.triggerToast('Ảnh tối đa 8 MB.', 'error');
      return;
    }

    const reader = new FileReader();
    reader.onload = (event) => {
      this.setState({ imgProduct: event.target.result, imageFile: file });
    };
    reader.onerror = () => this.triggerToast('Không đọc được tệp ảnh. Vui lòng chọn ảnh khác.', 'error');
    reader.readAsDataURL(file);
  };

  previewImage = (e) => {
    this.processFile(e.target.files[0]);
    e.target.value = '';
  };

  // Xử lý sự kiện kéo thả ảnh
  handleDrop = (e) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      this.processFile(e.dataTransfer.files[0]);
    }
  };

  handleDragOver = (e) => {
    e.preventDefault();
  };

  selectItem = (item) => {
    this.setState({
      txtID: item._id,
      txtName: item.name,
      txtCostPrice: item.costPrice ?? 0,
      txtPrice: item.price,
      cmbCategory: item.category ? item.category._id : '',
      cmbStatus: item.status || 'Active',
      imgProduct: item.image || '',
      imageFile: null,
      isEdit: true
    });
  };

  resetForm = () => {
    this.setState({
      txtID: '',
      txtName: '',
      txtCostPrice: '',
      txtPrice: '',
      cmbCategory: this.state.categories.length > 0 ? this.state.categories[0]._id : '',
      cmbStatus: 'Active',
      imgProduct: '',
      imageFile: null,
      isEdit: false,
      isSaving: false,
      isUploadingImage: false
    });
    if (this.fileInputRef) this.fileInputRef.value = '';
  };

  btnSaveClick = async (e) => {
    e.preventDefault();
    const {
      txtID, txtName, txtCostPrice, txtPrice, cmbCategory, cmbStatus,
      imgProduct, imageFile, isEdit, isSaving
    } = this.state;
    if (isSaving) return;
    const costPrice = Number(txtCostPrice);
    const salePrice = Number(txtPrice);

    if (!txtName.trim() || txtCostPrice === '' || !Number.isFinite(costPrice) || costPrice < 0 ||
        txtPrice === '' || !Number.isFinite(salePrice) || salePrice < 0 || !cmbCategory) {
      this.triggerToast('Vui lòng nhập đầy đủ thông tin bắt buộc!');
      return;
    }

    const config = { headers: { 'x-access-token': this.context.token } };
    this.setState({ isSaving: true, isUploadingImage: Boolean(imageFile) });

    try {
      let imageUrl = imgProduct;
      if (imageFile) {
        const formData = new FormData();
        formData.append('image', imageFile);
        const uploadResponse = await axios.post('/api/admin/products/upload-image', formData, config);
        imageUrl = uploadResponse.data?.url;
        if (!imageUrl) throw new Error('Cloudinary không trả về đường dẫn ảnh.');
        this.setState({ imgProduct: imageUrl, imageFile: null, isUploadingImage: false });
      }

      const product = {
        name: txtName.trim(),
        costPrice,
        price: salePrice,
        category: cmbCategory,
        status: cmbStatus,
        image: imageUrl
      };
      const response = isEdit
        ? await axios.put(`/api/admin/products/${txtID}`, product, config)
        : await axios.post('/api/admin/products', product, config);

      if (!response.data) throw new Error('Máy chủ chưa lưu được món ăn.');
      this.triggerToast(isEdit ? 'Cập nhật món ăn thành công!' : 'Thêm món ăn mới thành công!');
      this.apiGetProducts();
      this.resetForm();
    } catch (error) {
      this.setState({ isSaving: false, isUploadingImage: false });
      this.triggerToast(
        error.response?.data?.message || error.message || 'Không lưu được món ăn. Vui lòng thử lại.',
        'error'
      );
    }
  };

  btnDeleteClick = (id) => {
    this.setState({
      showConfirm: true,
      confirmMsg: 'Bạn có chắc chắn muốn xóa món ăn này không?',
      onConfirmCallback: () => {
        const config = { headers: { 'x-access-token': this.context.token } };
        axios.delete(`/api/admin/products/${id}`, config).then((res) => {
          if (res.data.success) {
            this.triggerToast('Đã xóa món ăn thành công!');
            this.apiGetProducts();
            this.resetForm();
          }
        });
      }
    });
  };

  render() {
    const { 
      products, categories, txtName, txtCostPrice, txtPrice, cmbCategory, cmbStatus, imgProduct, isEdit,
      isSaving, isUploadingImage, showConfirm, confirmMsg, showToast, toastMsg, toastType
    } = this.state;

    return (
      <div className="product-container">
        <h3 className="product-title">QUẢN LÝ THỰC ĐƠN & MÓN ĂN</h3>
        <div className="product-layout">
          
          {/* CỘT TRÁI: Form Chi tiết / Thêm mới sản phẩm */}
          <div className="product-form-card">
            <h4 style={{ marginBottom: '20px', color: '#4A2E2B' }}>
              {isEdit ? 'Chỉnh Sửa Món Ăn' : 'Thêm Món Ăn Mới'}
            </h4>
            <form>
              <div className="form-group">
                <label className="form-label">Tên Món Ăn *</label>
                <input
                  type="text"
                  className="form-input"
                  value={txtName}
                  onChange={(e) => this.setState({ txtName: e.target.value })}
                  placeholder="VD: Phở bò, Trà sữa..."
                />
              </div>

              <div className="form-group">
                <label className="form-label">Giá Vốn (VNĐ) *</label>
                <input
                  type="number"
                  min="0"
                  className="form-input"
                  value={txtCostPrice}
                  onChange={(e) => this.setState({ txtCostPrice: e.target.value })}
                  placeholder="VD: 25000"
                />
              </div>

              <div className="form-group">
                <label className="form-label">Giá Bán (VNĐ) *</label>
                <input
                  type="number"
                  className="form-input"
                  value={txtPrice}
                  onChange={(e) => this.setState({ txtPrice: e.target.value })}
                  placeholder="VD: 45000"
                />
              </div>

              <div className="form-group">
                <label className="form-label">Danh Mục Món *</label>
                <select
                  className="form-select"
                  value={cmbCategory}
                  onChange={(e) => this.setState({ cmbCategory: e.target.value })}
                >
                  {categories.map((cate) => (
                    <option key={cate._id} value={cate._id}>{cate.name}</option>
                  ))}
                </select>
              </div>

              <div className="form-group">
                <label className="form-label">Trạng Thái Món</label>
                <select
                  className="form-select"
                  value={cmbStatus}
                  onChange={(e) => this.setState({ cmbStatus: e.target.value })}
                >
                  <option value="Active">Còn món (Active)</option>
                  <option value="Inactive">Hết món (Inactive)</option>
                </select>
              </div>

              {/* Khung chọn ảnh hỗ trợ cả click và kéo thả (Drag and Drop) */}
              <div className="form-group">
                <label className="form-label">Hình Ảnh Món Ăn</label>
                <div 
                  className="image-upload-box" 
                  onClick={() => this.fileInputRef?.click()}
                  onDragOver={this.handleDragOver}
                  onDrop={this.handleDrop}
                >
                  <input 
                    type="file" 
                    accept="image/jpeg,image/png,image/webp" 
                    ref={ref => this.fileInputRef = ref} 
                    onChange={this.previewImage} 
                    style={{ display: 'none' }} 
                  />
                  {imgProduct ? (
                    <div className="preview-container">
                      <img src={imgProduct} alt="Preview" className="preview-img" />
                    </div>
                  ) : (
                    <div className="upload-placeholder">
                       Nhấn vào đây hoặc kéo thả ảnh vào khung
                    </div>
                  )}
                </div>
                <small className="image-upload-help">
                  JPG, PNG hoặc WebP · tối đa 8 MB · ảnh sẽ được lưu trên Cloudinary
                </small>
              </div>

              <div style={{ display: 'flex', gap: '10px', marginTop: '20px' }}>
                <button type="submit" onClick={this.btnSaveClick} className="btn-submit" disabled={isSaving}>
                  {isUploadingImage ? 'ĐANG TẢI ẢNH LÊN...' : isSaving ? 'ĐANG LƯU...' : isEdit ? 'CẬP NHẬT MÓN' : 'LƯU MÓN ĂN'}
                </button>
                {isEdit && (
                  <button type="button" onClick={this.resetForm} className="btn-cancel">
                    HỦY
                  </button>
                )}
              </div>
            </form>
          </div>

          {/* CỘT PHẢI: Bảng danh sách sản phẩm */}
          <div className="product-list-card">
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
              <h4 style={{ margin: 0, color: '#4A2E2B' }}>Danh Sách Món Ăn</h4>
              <span style={{ fontSize: '13px', color: '#666' }}>Tổng số: {products.length} món</span>
            </div>

            <table className="product-table">
              <thead>
                <tr>
                  <th>Hình Ảnh</th>
                  <th>Tên Món</th>
                  <th>Giá Bán</th>
                  <th>Giá Vốn</th>
                  <th>Danh Mục</th>
                  <th>Trạng Thái</th>
                  <th>Hành Động</th>
                </tr>
              </thead>
              <tbody>
                {products.map((item) => (
                  <tr key={item._id}>
                    <td>
                      {item.image ? (
                        <img src={item.image} alt={item.name} className="table-img" />
                      ) : (
                        <div style={{ width: '45px', height: '45px', backgroundColor: '#EEE', borderRadius: '8px' }} />
                      )}
                    </td>
                    <td style={{ fontWeight: 'bold' }}>{item.name}</td>
                    <td style={{ color: '#C85A32', fontWeight: 'bold' }}>
                      {item.price ? item.price.toLocaleString('vi-VN') + ' đ' : '0 đ'}
                    </td>
                    <td className="product-cost-price">
                      {Number(item.costPrice || 0).toLocaleString('vi-VN')} đ
                    </td>
                    <td>{item.category ? item.category.name : 'N/A'}</td>
                    <td>
                      <span className={item.status === 'Active' ? 'badge-active' : 'badge-inactive'}>
                        {item.status === 'Active' ? 'Còn món' : 'Hết món'}
                      </span>
                    </td>
                    <td>
                      <button onClick={() => this.selectItem(item)} className="btn-edit">
                        Sửa
                      </button>
                      <button onClick={() => this.btnDeleteClick(item._id)} className="btn-delete">
                        Xóa
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

        </div>

        {/* CUSTOM CONFIRM MODAL (Ở GIỮA MÀN HÌNH) */}
        {showConfirm && (
          <div className="modal-backdrop">
            <div className="modal-card">
              <div className="modal-title">Xác Nhận Thao Tác</div>
              <div className="modal-message">{confirmMsg}</div>
              <div className="modal-actions">
                <button 
                  className="modal-btn-confirm" 
                  onClick={() => {
                    this.setState({ showConfirm: false });
                    if (this.state.onConfirmCallback) this.state.onConfirmCallback();
                  }}
                >
                  Đồng ý
                </button>
                <button 
                  className="modal-btn-cancel" 
                  onClick={() => this.setState({ showConfirm: false })}
                >
                  Hủy
                </button>
              </div>
            </div>
          </div>
        )}

        {/* TOAST THÀNH CÔNG (Ở GÓC TRÊN BÊN TRÁI) */}
        {showToast && (
          <div className={`toast-top-left ${toastType}`} role={toastType === 'error' ? 'alert' : 'status'}>
            <span className="toast-icon">{toastType === 'error' ? '!' : '✓'}</span>
            <span>{toastMsg}</span>
          </div>
        )}

      </div>
    );
  }
}

export default Product;
